  static int get totalPhrases => phrases.length;
  
  static List<ExtendedPhrase> getPhrasesByCategory(String category) {
    return phrases.where((p) => p.category == category).toList();
  }
  
  static List<ExtendedPhrase> search(String query) {
    final q = query.toLowerCase();
    return phrases.where((p) =>
      p.textFr.toLowerCase().contains(q) ||
      p.textTr.toLowerCase().contains(q) ||
      p.textEn.toLowerCase().contains(q) ||
      p.tags.any((t) => t.toLowerCase().contains(q))
    ).toList();
  }
